#!/usr/bin/env python3
"""Regenerate the generated parts of sample_data/ and validate the golden set.

    python build_sample_data.py

Hand-written (edit directly):  sample_data/docs/*.md except the five reference pages below
Generated by this script:      sample_data/docs/error-codes-*.md, agent-config-reference.md,
                               nimbusctl-reference.md, sample_data/tickets.jsonl, sample_data/golden.jsonl

Everything here is fictional. The corpus is built to be hard for a retriever in specific, labeled
ways: look-alike error codes and config keys (exact tokens matter), outdated 2.x / v1 / "classic"
pages that contradict the current ones, tickets about similar symptoms with different causes, and
questions that share no vocabulary with the passage that answers them.

Golden `relevant` entries are either a whole document ("ticket:T-1006") or one section
("doc:alerting#maintenance-windows"; the part after # is the heading turned into a slug, exactly
like a markdown anchor). In this file a section may be written as a unique prefix of its slug
("doc:error-codes-ingestion#nm-4012"); the script expands it and fails on anything ambiguous,
missing, or not visible at the asker's access level.
"""
from __future__ import annotations

import json
from collections import Counter
from pathlib import Path

import settings
from ingest import chunk_document, load_documents

DATA = Path(__file__).resolve().parent / "sample_data"

