def front_matter(title: str, slug: str, updated: str) -> str:
    return (f"---\ntitle: {title}\naccess: public\n"
            f"url: https://docs.nimbus-monitor.example/{slug}\nupdated: {updated}\n---\n# {title}\n\n")


def write_reference_pages() -> None:
    for slug, (title, updated, codes) in ERROR_PAGES.items():
        body = front_matter(title, slug, updated)
        body += "The most common codes (NM-1001, NM-1002, NM-4021, NM-4029, NM-5003) are explained in Troubleshooting and Error Codes.\n"
        for code, name, text in codes:
            body += f"\n## {code}: {name}\n\n{text}\n"
        (DATA / "docs" / f"{slug}.md").write_text(body, encoding="utf-8")

    body = front_matter("Agent Configuration Reference (agent.yaml)", "agent-config-reference", "2026-10-25")
    body += "Every setting in `/etc/nimbus/agent.yaml` for agent 3.4. Restart the agent after changing the file.\n"
    for key, text in CONFIG_KEYS:
        body += f"\n## {key}\n\n`{key}`: {text}\n"
    (DATA / "docs" / "agent-config-reference.md").write_text(body, encoding="utf-8")

    body = front_matter("nimbusctl Command Reference", "nimbusctl-reference", "2026-10-25")
    body += "`nimbusctl` is installed with the agent and must be run as root or as the `nimbus` user.\n"
    for cmd, text in CLI:
        body += f"\n## {cmd}\n\n{text}\n"
    (DATA / "docs" / "nimbusctl-reference.md").write_text(body, encoding="utf-8")


