def write_tickets() -> None:
    with open(DATA / "tickets.jsonl", "w", encoding="utf-8") as f:
        for tid, access, area, date, title, problem, resolution in TICKETS:
            f.write(json.dumps({"id": tid, "title": title, "problem": problem, "resolution": resolution,
                                "product_area": area, "access": access, "resolved_at": date}) + "\n")


def build_golden(chunks: list[dict]) -> list[dict]:
    level = {c["section_id"]: c["access_level"] for c in chunks}
    level.update({c["doc_id"]: c["access_level"] for c in chunks})
    rows = []
    for n, (qtype, access, question, relevant, reference) in enumerate(GOLDEN, start=1):
        resolved = []
        for ref in relevant:
            matches = sorted({k for k in level if k == ref or ("#" in ref and k.startswith(ref + "-"))})
            if ref in matches:
                matches = [ref]
            if len(matches) != 1:
                raise SystemExit(f"G{n:02d}: {ref!r} matches {matches or 'nothing'}")
            if level[matches[0]] > settings.ACCESS_LEVELS[access]:
                raise SystemExit(f"G{n:02d}: {matches[0]} is above the asker's level ({access})")
            resolved.append(matches[0])
        rows.append({"id": f"G{n:02d}", "type": qtype, "question": question, "user_access": access,
                     "relevant": resolved, "reference_answer": reference, "answerable": bool(resolved)})
    return rows


def main() -> None:
    write_reference_pages()
    write_tickets()
    docs = load_documents(DATA)
    chunks = [c for d in docs for c in chunk_document(d)]
    golden = build_golden(chunks)
    with open(DATA / "golden.jsonl", "w", encoding="utf-8") as f:
        for g in golden:
            f.write(json.dumps(g) + "\n")
    by_access = Counter(c["access"] for c in chunks)
    print(f"documents: {sum(d['doc_type'] == 'doc' for d in docs)} docs + "
          f"{sum(d['doc_type'] == 'ticket' for d in docs)} tickets -> {len(chunks)} chunks {dict(by_access)}")
    print(f"golden: {len(golden)} questions {dict(Counter(g['type'] for g in golden))}")


if __name__ == "__main__":
    main()
